solution.solution.cpp:
#include <cstdint>
#include <cstring>
#include <optional>
#include <vector>

static void append32(std::vector<std::uint8_t>& out, std::int64_t v)
{
    const auto u{ static_cast<std::uint32_t>(static_cast<std::int32_t>(v)) };
    for (int i{ 0 }; i < 4; ++i) out.push_back(static_cast<std::uint8_t>(u >> (8 * i)));
}

static bool fits32(std::int64_t v) { return v >= INT32_MIN && v <= INT32_MAX; }

std::vector<std::uint8_t> encodeJump(std::uint64_t from, std::uint64_t to)
{
    const auto shortDisp{ static_cast<std::int64_t>(to - (from + 2)) };
    if (shortDisp >= -128 && shortDisp <= 127) return { 0xEB, static_cast<std::uint8_t>(static_cast<std::int8_t>(shortDisp)) };
    const auto nearDisp{ static_cast<std::int64_t>(to - (from + 5)) };
    if (fits32(nearDisp)) { std::vector<std::uint8_t> out{ 0xE9 }; append32(out, nearDisp); return out; }
    std::vector<std::uint8_t> out{ 0xFF, 0x25, 0, 0, 0, 0 };
    for (int i{ 0 }; i < 8; ++i) out.push_back(static_cast<std::uint8_t>(to >> (8 * i)));
    return out;
}

std::optional<std::vector<std::uint8_t>> encodeCall(std::uint64_t from, std::uint64_t to)
{
    const auto disp{ static_cast<std::int64_t>(to - (from + 5)) };
    if (!fits32(disp)) return std::nullopt;
    std::vector<std::uint8_t> out{ 0xE8 };
    append32(out, disp);
    return out;
}

std::optional<std::uint64_t> branchTarget(const std::vector<std::uint8_t>& code, std::size_t at, std::uint64_t address)
{
    const auto have = [&](std::size_t n) { return at + n <= code.size(); };
    const auto rel32 = [&](std::size_t from) { std::int32_t d; std::memcpy(&d, &code[from], 4); return d; };
    if (!have(1)) return std::nullopt;
    const std::uint8_t op{ code[at] };
    if ((op == 0xEB || (op >= 0x70 && op <= 0x7F)) && have(2))
        return address + 2 + static_cast<std::uint64_t>(static_cast<std::int64_t>(static_cast<std::int8_t>(code[at + 1])));
    if ((op == 0xE9 || op == 0xE8) && have(5))
        return address + 5 + static_cast<std::uint64_t>(static_cast<std::int64_t>(rel32(at + 1)));
    if (op == 0x0F && have(6) && code[at + 1] >= 0x80 && code[at + 1] <= 0x8F)
        return address + 6 + static_cast<std::uint64_t>(static_cast<std::int64_t>(rel32(at + 2)));
    return std::nullopt;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("short, near and absolute jumps") {
    CHECK(encodeJump(0x1000, 0x1010) == (Bytes{ 0xEB, 0x0E }));
    CHECK(encodeJump(0x1000, 0x1000) == (Bytes{ 0xEB, 0xFE }));
    CHECK(encodeJump(0x1000, 0x1081) == (Bytes{ 0xEB, 0x7F }));
    CHECK(encodeJump(0x1000, 0x1082) == (Bytes{ 0xE9, 0x7D, 0x00, 0x00, 0x00 }));
    CHECK(encodeJump(0x1400010A0, 0x140001200) == (Bytes{ 0xE9, 0x5B, 0x01, 0x00, 0x00 }));
    CHECK(encodeJump(0x140002000, 0x140001000) == (Bytes{ 0xE9, 0xFB, 0xEF, 0xFF, 0xFF }));
    CHECK(encodeJump(0x140001000, 0x7FF600000000) == (Bytes{ 0xFF, 0x25, 0, 0, 0, 0, 0x00, 0x00, 0x00, 0x00, 0xF6, 0x7F, 0x00, 0x00 }));
}
TEST("calls") {
    const auto c{ encodeCall(0x401000, 0x402000) };
    CHECK(c.has_value());
    if (c) CHECK(*c == (Bytes{ 0xE8, 0xFB, 0x0F, 0x00, 0x00 }));
    CHECK(!encodeCall(0x140001000, 0x7FF600000000).has_value());
}
TEST("decoding targets") {
    CHECK_EQ(branchTarget({ 0xE8, 0xFB, 0x0F, 0x00, 0x00 }, 0, 0x401000).value_or(0), 0x402000ull);
    CHECK_EQ(branchTarget({ 0x90, 0xEB, 0xFE }, 1, 0x1001).value_or(0), 0x1001ull);
    CHECK_EQ(branchTarget({ 0x74, 0x0C }, 0, 0x2000).value_or(0), 0x200Eull);
    CHECK_EQ(branchTarget({ 0x7C, 0xF0 }, 0, 0x2000).value_or(0), 0x1FF2ull);
    CHECK_EQ(branchTarget({ 0x0F, 0x85, 0x20, 0x01, 0x00, 0x00 }, 0, 0x3000).value_or(0), 0x3126ull);
    CHECK_EQ(branchTarget({ 0xE9, 0xFB, 0xEF, 0xFF, 0xFF }, 0, 0x140002000).value_or(0), 0x140001000ull);
    CHECK(!branchTarget({ 0xC3 }, 0, 0).has_value());
    CHECK(!branchTarget({ 0xE9, 0x00 }, 0, 0).has_value());
    CHECK(!branchTarget({}, 0, 0).has_value());
}
TEST("round trip") {
    for (std::uint64_t to : { 0x1005ull, 0x1100ull, 0x0F00ull, 0x50000000ull }) {
        const Bytes j{ encodeJump(0x1000, to) };
        CHECK_EQ(branchTarget(j, 0, 0x1000).value_or(0), to);
    }
}

